const fs = require('fs');
const pmtiles = require('pmtiles');
async function run() {
  const p = new pmtiles.PMTiles('http://localhost:8080/gaia.pmtiles');
  const arrow = require('apache-arrow');
  console.log('Fetching metadata...');
  await p.getMetadata();
  let success = 0;
  for (let z = 0; z <= 2; z++) {
    for (let x = 0; x < Math.pow(2, z); x++) {
      for (let y = 0; y < Math.pow(2, z); y++) {
         try {
           const tile = await p.getZxy(z, x, y);
           if (tile) {
             const u8 = new Uint8Array(tile.data);
             const table = arrow.tableFromIPC(u8);
             table.getChild('x_norm').toArray();
             success++;
           }
         } catch(e) {
           console.error('Error on tile', z, x, y, e);
         }
      }
    }
  }
  console.log('Successfully loaded', success, 'tiles');
}
run();
